record.field:
{
                "type": "object",
                "properties": {
                    "model": {"type": "string", "description": "Odoo model technical name (e.g. sale.order, res.partner)"},
                    "domain": {"type": "array", "description": "Odoo domain list (e.g. [['state', '=', 'sale']])"},
                    "fields": {"type": "array", "items": {"type": "string"}, "description": "List of field names to read"},
                    "limit": {"type": "integer", "description": "Maximum number of records to return (default: 20)"}
                },
                "required": ["model"]
            }

{
                "type": "object",
                "properties": {
                    "model": {"type": "string", "description": "Odoo model technical name"},
                    "values": {"type": "object", "description": "Dictionary of field values to set"}
                },
                "required": ["model", "values"]
            }

{
                "type": "object",
                "properties": {
                    "model": {"type": "string", "description": "Odoo model technical name"},
                    "ids": {"type": "array", "items": {"type": "integer"}, "description": "List of record IDs to update"},
                    "values": {"type": "object", "description": "Dictionary of field values to write"}
                },
                "required": ["model", "ids", "values"]
            }

{
                "type": "object",
                "properties": {
                    "model": {"type": "string", "description": "Odoo model technical name"},
                    "ids": {"type": "array", "items": {"type": "integer"}, "description": "List of record IDs to delete"}
                },
                "required": ["model", "ids"]
            }

{
                "type": "object",
                "properties": {
                    "model": {"type": "string", "description": "Odoo model technical name"},
                    "question": {"type": "string", "description": "Analysis task or question to answer"},
                    "domain": {"type": "array", "description": "Odoo domain list filter"},
                    "fields": {"type": "array", "items": {"type": "string"}, "description": "Fields to inspect"},
                    "limit": {"type": "integer", "description": "Record limit"}
                },
                "required": ["model", "question"]
            }
